package com.library.catalogattributes;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.concurrent.*;
import static com.library.catalogattributes.CatalogAttributeSupport.*;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="MYSQL_TEST_URL",matches=".+")
@SpringBootTest(properties={"spring.flyway.enabled=true","spring.sql.init.mode=never","bootstrap.admin.username=admin","bootstrap.admin.password=CatalogSyntheticAdministrator123","mybatis-plus.configuration.log-impl=org.apache.ibatis.logging.nologging.NoLoggingImpl"})
public class MySqlCatalogAttributeServiceTest extends CatalogAttributeServiceTest {
    @DynamicPropertySource static void mysql(DynamicPropertyRegistry r){String url=System.getenv("MYSQL_TEST_URL");if(url==null||!url.matches("jdbc:mysql://[^/]+/library_repair_tests(?:\\?.*)?"))throw new IllegalStateException("Disposable schema only");r.add("spring.datasource.url",()->url);r.add("spring.datasource.driver-class-name",()->"com.mysql.cj.jdbc.Driver");r.add("spring.datasource.username",()->System.getenv("MYSQL_TEST_USER"));r.add("spring.datasource.password",()->System.getenv("MYSQL_TEST_PASSWORD"));}
    @Test void busyCatalogRollsBackWholeConfirmationAndPreservesOriginalKey()throws Exception{long b=book();JsonNode p=service.preview(set(input(b,"MANUAL"),"bindingCode","BOARD"),admin);CountDownLatch held=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService pool=Executors.newSingleThreadExecutor();try{Future<?> lock=pool.submit(()->new TransactionTemplate(transactions).execute(s->{jdbc.queryForObject("SELECT id FROM inventory_mutex WHERE id=1 FOR UPDATE",Long.class);held.countDown();try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new RuntimeException(e);}return null;}));assertTrue(held.await(5,TimeUnit.SECONDS));reason("CATALOG_BUSY",()->confirm(p));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_book_attribute WHERE book_id=?",Integer.class,b));assertEquals("PREVIEWED",service.get(p.path("requestId").asLong(),admin).path("state").asText());release.countDown();lock.get(10,TimeUnit.SECONDS);assertTrue(confirm(p).path("book").path("changed").asBoolean());}finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(10,TimeUnit.SECONDS));}}
    @Test void legacyTitleAndConfirmShareCatalogLockWithoutReverseOrder()throws Exception{long b=book();JsonNode p=service.preview(set(input(b,"MANUAL"),"bindingCode","BOARD"),admin);CountDownLatch updated=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService pool=Executors.newSingleThreadExecutor();try{Future<?> update=pool.submit(()->{authenticate();try{return new TransactionTemplate(transactions).execute(s->{metadataTitle(b,"竞争登记名");updated.countDown();try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new RuntimeException(e);}return null;});}finally{clear();}});assertTrue(updated.await(5,TimeUnit.SECONDS));reason("CATALOG_BUSY",()->confirm(p));release.countDown();update.get(10,TimeUnit.SECONDS);reason("REVISION_CONFLICT",()->confirm(p));assertEquals(1,service.attributes(b,admin).path("profile").path("revision").asInt());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_attribute_event WHERE book_id=?",Integer.class,b));}finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(10,TimeUnit.SECONDS));}}
}
